// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b CardDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// cards_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) cards_by_keys(keys []string) ![]CardNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.cards().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]CardNode{}
	for row in rows {
		by_key[row.card.id.str()] = row
	}
	mut found := []CardNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'cards'
			}
		}
	}
	return found
}
